 private boolean active(){return GardenSession.expeditionSeats>0;}
 private void layout(){unit=BattleHudLayout.unit(getWidth(),getHeight());w=getWidth()/unit;h=getHeight()/unit;}
 void frame(long nanos){if(!active()){if(largeHud.active())invalidate();return;}long now=nanos/1000000;if(now-readAt>=70){readAt=now;int[] d=NativeInterface.expeditionSnapshot();if(d!=null&&d.length>11){snap=new ExpeditionSnapshot(d);observeSound();slots.expedition(snap,StaticBits.team);sight=NativeInterface.minimapSnapshot(false);int a=snap.seat(StaticBits.team);serial=Math.max(serial,d[a+7]);if(d[a+7]>ack){ack=d[a+7];note(errors[Math.max(0,Math.min(errors.length-1,d[a+8]))]);}OperationsSnapshot ops=orders().facts();if(ops!=null){long x=0,y=0,n=0;int[] selected=orders().selectedPosition();for(int g=0;g<3;g++){int b=ops.group(StaticBits.team,g),count=ops.raw[b];x+=(long)ops.raw[b+1]*count;y+=(long)ops.raw[b+2]*count;n+=count;}if(n>0){float xx=selected==null?x/(float)n:selected[0],yy=selected==null?y/(float)n:selected[1];surface().camera.follow(xx,yy);if(teleports>=0&&teleports!=d[a+9]){old().resetControl();surface().camera.relocate(xx,yy);}teleports=d[a+9];}}}}
  surface().camera.frame(nanos);surface().refreshHeldTargets(old());surface().applyCamera();invalidate();}
 private void observeSound(){int a=snap.seat(StaticBits.team);boolean baseline=audioTime<0||snap.time<audioTime;int cue=-1;if(!baseline){if(snap.raw[a+4]>audioCoins||snap.holeStock>audioStock[2]||snap.holeUntil>audioHoleUntil)cue=AudioEvents.ITEM;for(int k=0;k<2;k++)if(snap.raw[a+11+k]>audioStock[k]||snap.raw[a+19+k]>audioReady[k])cue=AudioEvents.ITEM;if(snap.raw[a+7]>ack&&snap.raw[a+8]!=0)cue=AudioEvents.ALERT;}audioTime=snap.time;audioCoins=snap.raw[a+4];audioStock[2]=snap.holeStock;audioHoleUntil=snap.holeUntil;for(int k=0;k<2;k++){audioStock[k]=snap.raw[a+11+k];audioReady[k]=snap.raw[a+19+k];}if(cue>=0)surface().audio().play(cue);}
 private void note(String s){notice=s;noticeUntil=android.os.SystemClock.uptimeMillis()+3500;invalidate();}
