 private void zone(Canvas c,int x,int y,int radius,int color){MyGLSurfaceView v=surface();float xx=(v.getLeft()+v.camera.screenX(x,v.getWidth()))/unit,yy=(v.getTop()+v.camera.screenY(y,v.getHeight()))/unit,r=radius*v.getWidth()/v.camera.viewWidth/unit;p.setStyle(Paint.Style.FILL);p.setColor((color&0xffffff)|0x16000000);c.drawCircle(xx,yy,r,p);p.setStyle(Paint.Style.STROKE);p.setColor((color&0xffffff)|0xa0000000);p.setStrokeWidth(1.1f);c.drawCircle(xx,yy,r,p);p.setStyle(Paint.Style.FILL);}
