 private RectF mapBox(){float mh=h-120,mw=mh*surface().camera.width/surface().camera.height;return new RectF(w/2-mw/2,65,w/2+mw/2,65+mh);}
 private RectF mapImage(RectF frame,boolean expanded){float z=expanded?mapZoom:1,cx=frame.centerX()+(expanded?mapDX:0),cy=frame.centerY()+(expanded?mapDY:0);return new RectF(cx-frame.width()*z/2,cy-frame.height()*z/2,cx+frame.width()*z/2,cy+frame.height()*z/2);}
 private float mx(int x,RectF r){return r.left+x*r.width()/surface().camera.width;}
 private float my(int y,RectF r){return r.top+(surface().camera.height-1-y)*r.height()/surface().camera.height;}
