 private void marker(Canvas c,RectF r,int x,int y,int team,float radius,String label){float xx=mx(x,r),yy=my(y,r);p.setStyle(Paint.Style.FILL);p.setColor(0xff193238);c.drawCircle(xx,yy,radius+1.5f,p);p.setColor(TeamPalette.color(team));c.drawCircle(xx,yy,radius,p);if(label!=null)text(c,label,xx,yy+3,8,Color.WHITE);}
 private final double[] mapSumX=new double[10],mapSumY=new double[10],mapWeight=new double[10],mapNearest=new double[10];
 private final int[] mapAnchor=new int[10];
 private void drawEnemySight(Canvas c,RectF r,boolean expanded,int own){
  if(snap.recon!=own||sight==null||sight.length<5)return;
  java.util.Arrays.fill(mapSumX,0);java.util.Arrays.fill(mapSumY,0);java.util.Arrays.fill(mapWeight,0);java.util.Arrays.fill(mapNearest,Double.MAX_VALUE);java.util.Arrays.fill(mapAnchor,-1);
  // Preserve every visible distribution sample; label each army once rather
  // than placing an outlined numbered badge on every 32-cell sample.
  for(int i=0;i<sight[4];i++){int b=5+i*4;if(b+3>=sight.length)break;int t=sight[b],n=sight[b+3];if(t<0||t>=10||t==own||n<=0)continue;
   mapSumX[t]+=(double)sight[b+1]*n;mapSumY[t]+=(double)sight[b+2]*n;mapWeight[t]+=n;
   p.setColor(TeamPalette.color(t));p.setStyle(Paint.Style.FILL);c.drawCircle(mx(sight[b+1],r),my(sight[b+2],r),expanded?2.2f:1.2f,p);
  }
  // Anchor the badge to a received sample, never an invented point in a wall
  // or a hidden full-army centre. Visibility remains server/native filtered.
  for(int i=0;i<sight[4];i++){int b=5+i*4;if(b+3>=sight.length)break;int t=sight[b];if(t<0||t>=10||t==own||mapWeight[t]==0)continue;double dx=sight[b+1]-mapSumX[t]/mapWeight[t],dy=sight[b+2]-mapSumY[t]/mapWeight[t],d=dx*dx+dy*dy;if(d<mapNearest[t]){mapNearest[t]=d;mapAnchor[t]=b;}}
  for(int t=0;t<10;t++){int b=mapAnchor[t];if(b>=0)marker(c,r,sight[b+1],sight[b+2],t,expanded?5:2.3f,expanded?""+(t+1):null);}
 }
 private void resourceMark(Canvas c,int kind,float x,float y,float radius){
  p.setStyle(Paint.Style.FILL);p.setColor(0xdd193238);c.drawCircle(x,y,radius+1.2f,p);p.setColor(kind==2?0xffffca54:kind==0?0xff77ddff:kind==1?0xffffe5b0:0xfff4f5e4);p.setStrokeWidth(1.4f);
  if(kind==2){c.drawCircle(x,y,radius,p);p.setColor(0xff92712b);c.drawLine(x,y-radius*.6f,x,y+radius*.6f,p);}
  else if(kind==0){for(int a=0;a<3;a++){double t=a*Math.PI/3;c.drawLine(x-(float)Math.cos(t)*radius,y-(float)Math.sin(t)*radius,x+(float)Math.cos(t)*radius,y+(float)Math.sin(t)*radius,p);}}
  else if(kind==1){Path q=new Path();q.moveTo(x,y-radius);q.lineTo(x+radius,y);q.lineTo(x,y+radius);q.lineTo(x-radius,y);q.close();c.drawPath(q,p);}
  else if(kind==4)slots.holeMarker(c,x,y,radius);else c.drawRect(x-radius*.8f,y-radius*.8f,x+radius*.8f,y+radius*.8f,p);
 }
