 public boolean back(){if(!active())return largeHud.back();if(aim>=0){aim=-1;note(com.xenris.liquidwarsos.BattleText.t("已取消，道具保留","Canceled; item retained"));return true;}if(modal!=0){modal=0;invalidate();return true;}return false;}
 boolean blocks(float x,float y){if(!active())return largeHud.blocks(x,y);layout();x/=unit;y/=unit;return modal!=0||aim>=0||topTarget(x,y)>=0||mini().contains(x,y)||(snap!=null&&snap.count(StaticBits.team)>0&&slots.hit(x,y,w,h)>=0)||(x>w-142&&y>h-107&&y<h-80)||(snap!=null&&snap.raw[snap.seat(StaticBits.team)+39]>0&&Math.abs(x-w/2)<125&&y>h-106&&y<h-75);}
 private void drawBlackHole(Canvas c,WorldCamera cam){
  MyGLSurfaceView v=surface();
  float left=v.getLeft()/unit,top=v.getTop()/unit,width=v.getWidth()/unit,height=v.getHeight()/unit;
  c.save();c.clipRect(left,top,left+width,top+height);
  Bitmap icon=slots.blackHoleIcon();
  if(icon!=null)for(int i=0;i<snap.loot;i++){
   int at=snap.lootBase+i*5;
   if(snap.raw[at+1]!=ExpeditionSnapshot.BLACK_HOLE_LOOT)continue;
   float x=left+cam.screenX(snap.raw[at+2],width),y=top+cam.screenY(snap.raw[at+3],height);
   if(x<left-20||x>left+width+20||y<top-20||y>top+height+20)continue;
   int facts=snap.raw[snap.seat(i/4)+13+i%4];
   float fraction=Math.min(1,(facts&2047)/1200f);
   float half=Math.max(5,Math.min(25,8*width/cam.viewWidth))*(.5f+.5f*fraction);
   boolean filter=p.isFilterBitmap();p.setFilterBitmap(false);p.setColor(Color.WHITE);
   c.drawBitmap(icon,null,new RectF(x-half,y-half,x+half,y+half),p);p.setFilterBitmap(filter);
   if(fraction<1){p.setColor(0xdd202032);c.drawRect(x-half,y-half-4,x+half,y-half-2,p);
    p.setColor(0xffc1a1fa);c.drawRect(x-half,y-half-4,x-half+2*half*fraction,y-half-2,p);}
  }
  if(snap.holeUntil>snap.time)blackHole.draw(c,cam,left,top,width,height,1,NativeInterface.playTimeMillis(),snap.holeStart,snap.holeUntil,snap.holeAbsorbed,snap.lastHoleAbsorb);
  c.restore();
 }
 private void send(int kind,int x,int y){if(snap==null)return;int seq=++serial;if(!NativeInterface.expeditionCommand(StaticBits.team,seq,kind,orders().selectedGroup(),x,y))note(com.xenris.liquidwarsos.BattleText.t("命令队列繁忙，请重试","Command queue busy; please retry"));else note(com.xenris.liquidwarsos.BattleText.t("已提交，等待生效","Sent; awaiting activation"));aim=-1;}
 void joystickItem(int kind){if(snap!=null&&kind>=0&&kind<ActiveSlots.COUNT)choose(kind);}
 private void choose(int kind){if(snap.bag(StaticBits.team,kind)==0){note(names[kind]+com.xenris.liquidwarsos.BattleText.t("：先拾取，最多累积10个",": collect first; up to 10 per type"));return;}if(snap.cooldown(StaticBits.team,kind)>0){note(com.xenris.liquidwarsos.BattleText.t("冷却中，库存保留","Cooling down; item retained"));return;}send(kind,0,0);}
 private void pending(){int a=snap.seat(StaticBits.team),kind=snap.raw[a+39];if(kind==3){aim=3;modal=0;orders().cancelForModal();return;}java.util.ArrayList<Integer> ts=new java.util.ArrayList<>();java.util.ArrayList<String> labels=new java.util.ArrayList<>();for(int t=0;t<snap.teams;t++)if(t!=StaticBits.team&&snap.count(t)>0){ts.add(t);labels.add(com.xenris.liquidwarsos.BattleText.t("席位 ","Seat ")+(t+1));}AlertDialog d=new AlertDialog.Builder(getContext()).setTitle(com.xenris.liquidwarsos.BattleText.t("选择敌军 · 隐藏或受保护目标不可用","Choose an enemy · Hidden or protected targets are unavailable")).setItems(labels.toArray(new String[0]),(v,k)->sendPending(ts.get(k),0)).setNegativeButton(com.xenris.liquidwarsos.BattleText.t("取消","Cancel"),null).create();d.show();fontDialog(d);}
 private void sendPending(int x,int y){int nonce=snap.raw[snap.seat(StaticBits.team)+40];NativeInterface.expeditionCommand(StaticBits.team,++serial,101,nonce,x,y);aim=-1;}
 private void fontDialog(AlertDialog d){android.view.View root=d.getWindow().getDecorView();fontTree(root);}
 private void fontTree(View v){if(v instanceof TextView)((TextView)v).setTypeface(p.getTypeface());if(v instanceof android.view.ViewGroup){android.view.ViewGroup g=(android.view.ViewGroup)v;for(int i=0;i<g.getChildCount();i++)fontTree(g.getChildAt(i));}}
 public void guide(){TextView v=new TextView(getContext());v.setTypeface(p.getTypeface());v.setTextSize(15);int pad=(int)(18*getResources().getDisplayMetrics().density);v.setPadding(pad,pad,pad,pad);v.setText(com.xenris.liquidwarsos.BattleText.t("远征 · 2—10席自由混战\n\n每席轮流侦察60秒，非本回合小地图不显示敌军；主战场仅显示正常视野内敌军。淘汰席位留下空档，不给其他人额外侦察。两轮后按真实粒子数排名，同数并列。\n\n点击目标、长按拖动、松手续行；左下切换画线，选A/B/C分队分别下令。小地图点击展开，查看、定位镜头和下令三个模式互不混用。\n\n道具和金币都需持续贴近吞噬；缩小与碎粒显示进度，离开后进度保留。整轮道具全部吃完才刷新下一轮，金币独立刷新。\n\n经典自动道具拾取后按原规则生效，传送/结盟/死亡保持后续选择。右下为冻结、净化和黑洞，每种最多10个。黑洞在全图中心持续10秒，前1.5秒可正常移动和使用净化，之后吸力逐渐增加。引力线表示受到吸引。越近拉得越快，吸引包括己方在内的所有粒子，障碍物仍会阻挡粒子。进入黑洞即死亡。净化可解除己方本次吸引。冻结无需选目标，冻结所有敌军10秒，冷却30秒；净化可在被冻结时使用，立即解除己方全军冻结并免冻6秒，冷却8秒，未冻时也可预防使用。重复冻结不延长，自然解冻后免冻5秒。\n\n道具失效或取消不消耗。金币仅用于本局鞋子、护甲三级升级40/70/110金币，重开清零。本人出生区42格内防御2倍，离开失效；与最高护甲叠加至2.6倍。\n\n据点24颗驻守4秒占领，夺敌点先中立化；双方至少3颗争夺时停止。产兵点每2秒10颗，达初始兵力2倍或无空位暂停，不积欠；攻击点+15%。\n\n时间冻结按用户要求固定为10秒，两种模式使用同一套道具效果。","Expedition · 2–10 seats, free-for-all\n\nEach seat receives 60 seconds of scouting in turn. Only that seat sees enemies on its minimap; the battlefield shows enemies in normal sight. Eliminated seats leave a gap in the rotation. After two rounds, actual particle counts determine ranking; ties share a rank.\n\nTap a destination, hold and drag to follow, then release to continue. Switch to routes at the lower left. Select A/B/C to command squads. The expanded map separates viewing, camera positioning and issuing orders.\n\nItems and coins take sustained contact to consume. Shrinking models, fragments and a short bar show progress, which is retained when you leave. All items in a wave must be consumed before the next wave. Coins refresh independently.\n\nClassic automatic items retain their rules. Teleport, alliance and death items still require a follow-up selection. Freeze, Cleanse and Black Hole each stack to 10. A black hole lasts 10 seconds at the map center. The first 1.5 seconds allow normal movement and Cleanse before attraction ramps up. Fine strands mark affected particles. It pulls all particles, including yours. Obstacles still block particles. Closer particles move faster and die when they enter the core. Cleanse frees your army from that black hole. Freeze needs no target and freezes every enemy for 10 seconds, with a 30-second cooldown. Cleanse works while frozen, releases your entire army immediately and grants 6 seconds of immunity, with an 8-second cooldown; preventive use is allowed. Repeated freezes do not extend an existing freeze. Natural thaw grants 5 seconds of immunity.\n\nCanceled or invalid targeted casts retain the item. Coins buy shoes and armor for this match: three upgrades cost 40/70/110. Gear resets next match. Your army has twice the defense within 42 cells of its own spawn; leaving removes this bonus. With maximum armor, defense reaches 2.6 times normal.\n\nHold 24 units at an outpost for 4 seconds to capture it. Enemy ownership is neutralized first. Contests of at least 3 units per side pause capture. Growth outposts produce 10 units every 2 seconds, stopping at twice starting army size or if space is blocked, without queuing missed units. Attack outposts grant +15% attack.\n\nFreeze lasts 10 seconds. Both modes share the same item effects."));ScrollView s=new ScrollView(getContext());s.addView(v);AlertDialog d=new AlertDialog.Builder(getContext()).setView(s).setPositiveButton(com.xenris.liquidwarsos.BattleText.t("返回战场","Back to battle"),null).create();d.show();fontDialog(d);}
 private int topTarget(float x,float y){if(y>=8&&y<=35){if(x>=146&&x<=194)return 30;if(x>=200&&x<=248)return 31;for(int i=0;i<3;i++)if(x>=utilityX(i)&&x<=utilityX(i)+(i==0?50:48))return 32+i;if(x>=10&&x<=140)return 99;}return y>=8&&y<=42&&Math.abs(x-w/2)<=90?99:-1;}
 private int target(float x,float y){if(modal==2){if(y>=250&&y<=287&&x>=w/2-220&&x<=w/2+218)return x<w/2?60:61;return 62;}if(modal==1){if(x>w-108&&y<84)return 41;for(int i=0;i<3;i++)if(y>h-69&&y<h-40&&x>w/2-158+i*108&&x<w/2-56+i*108)return 42+i;return 45;}
  int top=topTarget(x,y);if(top>=0)return top;if(mini().contains(x,y))return 40;if(x>w-142&&x<w-16&&y>h-107&&y<h-80)return 50;int active=snap.count(StaticBits.team)>0?slots.hit(x,y,w,h):-1;if(active>=0)return active;if(snap.raw[snap.seat(StaticBits.team)+39]>0&&Math.abs(x-w/2)<125&&y>h-106&&y<h-75)return 71;if(aim>=0)return 70;return -1;}
 @Override public boolean onTouchEvent(MotionEvent e){if(!active())return largeHud.touch(e);if(snap==null)return false;layout();float x=e.getX()/unit,y=e.getY()/unit;int action=e.getActionMasked();if(action==MotionEvent.ACTION_DOWN){hit=target(x,y);if(hit<0)return false;downX=lastX=x;downY=lastY=y;moved=false;pinch=0;return true;}if(hit<0)return false;if(action==MotionEvent.ACTION_CANCEL){hit=-1;return true;}if(action==MotionEvent.ACTION_POINTER_DOWN&&modal==1){pinch=(float)Math.hypot(e.getX(0)-e.getX(1),e.getY(0)-e.getY(1));moved=true;return true;}
  if(action==MotionEvent.ACTION_MOVE){if(Math.hypot(x-downX,y-downY)>6)moved=true;if(modal==1&&hit==45){if(e.getPointerCount()>1){float n=(float)Math.hypot(e.getX(0)-e.getX(1),e.getY(0)-e.getY(1));if(pinch>0)mapZoom=Math.max(1,Math.min(4,mapZoom*n/pinch));pinch=n;}else{mapDX+=x-lastX;mapDY+=y-lastY;}RectF box=mapBox();mapDX=Math.max(-box.width()*(mapZoom-1)/2,Math.min(box.width()*(mapZoom-1)/2,mapDX));mapDY=Math.max(-box.height()*(mapZoom-1)/2,Math.min(box.height()*(mapZoom-1)/2,mapDY));invalidate();}lastX=x;lastY=y;return true;}
  if(action!=MotionEvent.ACTION_UP)return true;int clicked=hit;hit=-1;if(moved)return true;performClick();if(clicked<ActiveSlots.COUNT)choose(clicked);else if(clicked==71)pending();else if(clicked==30){WorldCamera cam=surface().camera;cam.toggle(cam.left+cam.viewWidth/2,cam.bottom+cam.viewHeight/2);}else if(clicked==31)surface().camera.detailToggle();else if(clicked==32){surface().audio().toggle();}else if(clicked==33)old().showFrameOptions();else if(clicked==34)guide();else if(clicked==40){orders().cancelForModal();modal=1;aim=-1;}else if(clicked==41||clicked==62)modal=0;else if(clicked>=42&&clicked<=44)tab=clicked-42;else if(clicked==50){orders().cancelForModal();modal=2;aim=-1;}else if(clicked==60||clicked==61)send(100,clicked-60,0);else if(clicked==45&&tab==0){resourceDetails(x,y);}else if(clicked==45&&tab>0&&mapBox().contains(x,y)){int[] v=atMap(x,y,mapImage(mapBox(),true));if(tab==1)surface().camera.pan(v[0],v[1]);else{orders().orderAt(v[0],v[1]);note(com.xenris.liquidwarsos.BattleText.t("已向所选分队下令","Order sent to selected squads"));}}else if(clicked==70){MyGLSurfaceView v=surface();sendPending(v.camera.mapX(e.getX()-v.getLeft(),v.getWidth()),v.camera.mapY(e.getY()-v.getTop(),v.getHeight()));}invalidate();return true;}
 @Override protected void onDetachedFromWindow(){largeHud.dispose();super.onDetachedFromWindow();}
